def transform(grid):
    # Fill erased cells in the repeated 1..9 horizontal sequences, inferring
    # each row's phase from its nonzero cells and leaving printed cells intact.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        vals = [v for v in row if v]
        if not vals:
            continue
        # For each zero, use nearest horizontal nonzero and continue the 1..9 cycle.
        for c, v in enumerate(row):
            if v:
                continue
            left = next((k for k in range(c-1, -1, -1) if row[k]), None)
            right = next((k for k in range(c+1, len(row)) if row[k]), None)
            if left is not None:
                out[r][c] = (row[left] - 1 + (c-left)) % 9 + 1
            elif right is not None:
                out[r][c] = (row[right] - 1 - (right-c)) % 9 + 1
    return out
