from collections import Counter


def transform(grid):
    """Rebuild the repeated color cycle with its duplicated prior-color diagonal."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    colors = sorted({v for row in grid for v in row if v != 0})
    if not colors:
        return [row[:] for row in grid]

    n = len(colors)
    rank = {v: i for i, v in enumerate(colors)}
    # Off-diagonal cells encode the regular horizontal cycle. The modal phase
    # tolerates erased rectangles and excludes the diagonal's repeated colors.
    phases = Counter(
        (rank[v] - c) % n
        for r, row in enumerate(grid)
        for c, v in enumerate(row)
        if v != 0 and r != c
    )
    phase = phases.most_common(1)[0][0] if phases else 0

    return [
        [colors[(phase + c - (1 if r == c else 0)) % n] for c in range(w)]
        for r in range(h)
    ]
